import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { Effect } from "effect"
import { it } from "@effect/vitest"
import { describe, expect } from "vitest"

const manifestPath = (directory: string) => join(directory, "manifest.json")

const temporaryDirectory = Effect.acquireRelease(
  Effect.sync(() => mkdtempSync(join(tmpdir(), "manifest-store-"))),
  (directory) => Effect.sync(() => rmSync(directory, { recursive: true, force: true }))
)

const writeManifest = (directory: string, entries: ReadonlyArray<string>) =>
  Effect.sync(() => {
    writeFileSync(manifestPath(directory), JSON.stringify({ entries }))
  })

const readManifest = (directory: string) =>
  Effect.sync(() => {
    const contents = readFileSync(manifestPath(directory), "utf8")
    return JSON.parse(contents) as { entries: Array<string> }
  })

describe("ManifestStore", () => {
  it("uses a stable manifest filename", () => {
    expect(manifestPath("cache")).toBe(join("cache", "manifest.json"))
  })

